def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def ranges(n, separators):
        out = []
        start = 0
        for s in separators:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    rows = ranges(h, sep_rows)
    cols = ranges(w, sep_cols)
