                i2, j2 = points[b]
                if i1 == i2:
                    for j in range(min(j1, j2), max(j1, j2) + 1):
                        painted.setdefault((i1, j), set()).add(color)
                elif j1 == j2:
                    for i in range(min(i1, i2), max(i1, i2) + 1):
